stage_a_raw:
{
  "decisions": [
    {
      "decision": "flow_variable_domain",
      "evidence": "\"Transportation Cost Per Unit\" and \"Demand of Each Retail Store (in units)\" — units are not stated to be indivisible",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "demand_constraint_direction",
      "evidence": "\"fulfill the demand at each retail location\" / \"meet all retail stores' demands\"",
      "options": [
        "sum_i x[i,j] >= demand[j]",
        "sum_i x[i,j] = demand[j]"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "sum_i x[i,j] >= demand[j]"
    },
    {
      "decision": "capacity_link_form",
      "evidence": "\"Supply Capacity of Each Distribution Center\" and \"opening costs of each distribution center\"",
      "options": [
        "sum_j x[i,j] <= capacity[i] * y[i]",
        "sum_j x[i,j] <= capacity[i], with x[i,j] <= demand[j]*y[i] linking"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "sum_j x[i,j] <= capacity[i] * y[i]"
    },
    {
      "decision": "objective_units_scale",
      "evidence": "\"Opening Costs ... (in dollars)\" and \"Transportation Cost Per Unit ... (in dollars)\"",
      "options": [
        "dollars (opening cost + per-unit cost * units)",
        "thousands of dollars"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "dollars (opening cost + per-unit cost * units)"
    },
    {
      "decision": "transport_cost_matrix_orientation",
      "evidence": "\"From Center 1: $5 to Store 1, $2 to Store 2, ...\"",
      "options": [
        "rows = distribution centers, columns = stores (trans_cost[(i,j)])",
        "rows = stores, columns = distribution centers (trans_cost[(j,i)])"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "rows = distribution centers, columns = stores (trans_cost[(i,j)])"
    },
    {
      "decision": "open_variable_domain",
      "evidence": "\"open the necessary distribution centers\"",
      "options": [
        "Binary",
        "NonNegativeReals in [0,1]"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "Binary"
    }
  ]
}
